 "content": "from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Locate the long L-shaped marker: a long horizontal and vertical arm
    # meeting at the corner. Its open quadrant indicates the target object.
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 8:
                continue
            horiz = []
            for dc in (-1, 1):
                n = 0; x = c + dc
                while 0 <= x < w and grid[r][x] == color:
                    n += 1; x += dc
                horiz.append((n, dc))
            vert = []
            for dr in (-1, 1):
                n = 0; y = r + dr
                while 0 <= y < h and grid[y][c] == color:
                    n += 1; y += dr
                vert.append((n, dr))
            for hn, hd in horiz:
                for vn, vd in vert:
                    if hn + 1 >= 5 and vn + 1 >= 4:
                        # candidate matching long-line L; target lies opposite arms
                        tr, tc = r - vd, c - hd
                        # collect non-background components and select nearest
                        seen = set(); comps=[]
                        for y in range(h):
                            for x in range(w):
                                if (y,x) in seen or grid[y][x] in (8, color): continue
                                col=grid[y][x]; q=[(y,x)]; seen.add((y,x)); comp=[]
                                while q:
                                    a,b=q.pop(); comp.append((a,b))
                                    for aa,bb in ((a-1,b),(a+1,b),(a,b-1),(a,b+1)):
                                        if 0<=aa<h and 0<=bb<w and (aa,bb) not in seen and grid[aa][bb]==col:
                                            seen.add((aa,bb)); q.append((aa,bb))
                                comps.append((col,comp))
                        eligible=[]
                        for col,comp in comps:
                            # Favor component in marker's open quadrant.
                            cy=sum(a for a,b in comp)/len(comp); cx=sum(b for a,b in comp)/len(comp)
                            if (cy-r)*(-vd)>0 and (cx-c)*(-hd)>0:
                                dist=min(abs(a-tr)+abs(b-tc) for a,b in comp)
                                eligible.append((dist,col,comp))
                        if eligible:
                            _,_,comp=min(eligible,key=lambda z:z[0])
                            out=[row[:] for row in grid]
                            for a,b in comp: out[a][b]=color
                            return out
    return [row[:] for row in grid]

if __name__ == '__main__':
    import json,sys
    print(json.dumps(transform(json.load(sys.stdin))))
",
